UPDATE stores AS s SET
 template_config=jsonb_set(coalesce(s.template_config,'{}'::jsonb),'{module_features}',bt.settings->'module_features',true),
 updated_at=now()
 FROM business_templates bt
 WHERE s.template_id=bt.id AND NOT coalesce(s.template_config,'{}'::jsonb) ? 'module_features'
 AND bt.settings ? 'module_features';
